    20	        StringBuilder csv = new StringBuilder();
    21	        csv.append("room,type,reservation,check_in,check_out\n");
    22	
    23	        String sql = "SELECT r.id, r.room_number, r.check_in, r.check_out " +
    24	            "FROM reservations r " +
    25	            "WHERE r.status IN ('CONFIRMED', 'CHECKED_IN', 'CHECKED_OUT') " +
    26	            "AND r.check_in <= ? " +
    27	            "AND r.check_out > ? " +
    28	            "ORDER BY r.room_number, r.id";
    29	
    30	        int occupiedRooms = 0;
    31	        try (Connection conn = DatabaseConfig.getConnection()) {
    32	            PreparedStatement stmt = conn.prepareStatement(sql);
    33	            stmt.setObject(1, date);
    34	            stmt.setObject(2, date);
    35	            ResultSet rs = stmt.executeQuery();
    36	
    37	            while (rs.next()) {
    38	                long reservationId = rs.getLong("id");
    39	                int roomNumber = rs.getInt("room_number");
    40	                LocalDate checkIn = rs.getObject("check_in", LocalDate.class);
    41	                LocalDate checkOut = rs.getObject("check_out", LocalDate.class);
    42	
