     1	package com.pousada.marealta.service;
     2	
     3	import java.math.BigDecimal;
     4	import java.math.RoundingMode;
     5	import java.time.LocalDate;
     6	import java.time.YearMonth;
     7	
     8	public class PricingService {
     9	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = BigDecimal.valueOf(1.20);
    10	    private static final BigDecimal DISCOUNT_RATE = BigDecimal.valueOf(0.15);
    11	    private static final BigDecimal ISS_RATE = BigDecimal.valueOf(0.05);
    12	
    13	    public static BigDecimal calculateNightlyPrice(BigDecimal baseRate, LocalDate date) {
    14	        if (isHighSeason(date)) {
    15	            return baseRate.multiply(HIGH_SEASON_MULTIPLIER).setScale(2, RoundingMode.HALF_EVEN);
    16	        }
    17	        return baseRate.setScale(2, RoundingMode.HALF_EVEN);
    18	    }
    19	
    20	    public static BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
    21	        BigDecimal subtotal = BigDecimal.ZERO;
    22	        LocalDate current = checkIn;
    23	        while (current.isBefore(checkOut)) {
    24	            subtotal = subtotal.add(calculateNightlyPrice(baseRate, current));
    25	            current = current.plusDays(1);
    26	        }
    27	        return subtotal.setScale(2, RoundingMode.HALF_EVEN);
    28	    }
    29	
    30	    public static BigDecimal calculateDiscount(BigDecimal subtotal, boolean isNonRefundable) {
    31	        if (isNonRefundable) {
    32	            return subtotal.multiply(DISCOUNT_RATE).setScale(2, RoundingMode.HALF_EVEN);
    33	        }
    34	        return BigDecimal.ZERO.setScale(2, RoundingMode.HALF_EVEN);
    35	    }
    36	
    37	    public static BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
    38	        return subtotal.subtract(discount).setScale(2, RoundingMode.HALF_EVEN);
    39	    }
    40	
    41	    public static BigDecimal calculateIssRetention(BigDecimal total) {
    42	        return total.multiply(ISS_RATE).setScale(2, RoundingMode.HALF_EVEN);
    43	    }
    44	
    45	    public static int calculateNights(LocalDate checkIn, LocalDate checkOut) {
    46	        return (int) java.time.temporal.ChronoUnit.DAYS.between(checkIn, checkOut);
    47	    }
    48	
    49	    private static boolean isHighSeason(LocalDate date) {
    50	        int month = date.getMonthValue();
    51	        int day = date.getDayOfMonth();
    52	
    53	        // July
    54	        if (month == 7) {
    55	            return true;
    56	        }
    57	
    58	        // December 15 to February 29
    59	        if (month == 12 && day >= 15) {
    60	            return true;
    61	        }
    62	        if (month == 1 || month == 2) {
    63	            return true;
    64	        }
    65	
    66	        return false;
    67	    }
    68	}
