    69	            "ORDER BY r.check_in, r.id";
    70	
    71	        BigDecimal totalAmount = BigDecimal.ZERO;
    72	        try (Connection conn = DatabaseConfig.getConnection()) {
    73	            PreparedStatement stmt = conn.prepareStatement(sql);
    74	            stmt.setInt(1, month.getYear());
    75	            stmt.setInt(2, month.getMonthValue());
    76	            ResultSet rs = stmt.executeQuery();
    77	
    78	            while (rs.next()) {
    79	                long reservationId = rs.getLong("id");
    80	                int roomNumber = rs.getInt("room_number");
    81	                LocalDate checkIn = rs.getObject("check_in", LocalDate.class);
    82	                LocalDate checkOut = rs.getObject("check_out", LocalDate.class);
    83	                String status = rs.getString("status");
    84	                BigDecimal amountPaid = rs.getBigDecimal("amount_paid");
    85	                BigDecimal refund = rs.getBigDecimal("refund");
    86	
    87	                BigDecimal netAmount = amountPaid.subtract(refund == null ? BigDecimal.ZERO : refund);
    88	
    89	                csv.append(reservationId).append(",")
    90	                    .append(roomNumber).append(",")
    91	                    .append(checkIn).append(",")
    92	                    .append(checkOut).append(",")
    93	                    .append(status).append(",")
    94	                    .append(formatAmount(netAmount)).append("\n");
    95	
    96	                totalAmount = totalAmount.add(netAmount);
    97	            }
    98	        }
    99	
   100	        csv.append("total,").append(formatAmount(totalAmount)).append("\n");
   101	        return csv.toString();
   102	    }
   103	
   104	    private static String formatAmount(BigDecimal amount) {
   105	        return amount.toPlainString();
   106	    }
   107	}

